Signed-off-by: J. Bruce Fields <bfields@redhat.com>

Here is the root cause:
The bug was caused by the `gss_proxy` not properly initializing the `svc_cred` structure, leading to the copying of uninitialized memory into `rsci.cred`. This resulted in a general protection fault when the NFS server attempted to use this uninitialized data, particularly in scenarios where the server did not have the `rpcsec_gss_krb5` module built.

Here is the patch:

 static int gssx_dec_option_array(struct xdr_stream *xdr,
 				 struct gssx_option_array *oa)
 {
 	struct svc_cred *creds;
 	u32 count, i;
 	__be32 *p;
 	int err;

 	p = xdr_inline_decode(xdr, 4);
 	if (unlikely(p == NULL))
 		return -ENOSPC;
 	count = be32_to_cpup(p++);
 	if (!count)
 		return 0;

 	/* we recognize only 1 currently: CREDS_VALUE */
 	oa->count = 1;

 	oa->data = kmalloc(sizeof(struct gssx_option), GFP_KERNEL);
 	if (!oa->data)
 		return -ENOMEM;

-	creds = kmalloc(sizeof(struct svc_cred), GFP_KERNEL);
+	creds = kzalloc(sizeof(struct svc_cred), GFP_KERNEL);
 	if (!creds) {
 		kfree(oa->data);
 		return -ENOMEM;
 	}

 	oa->data[0].option.data = CREDS_VALUE;
 	oa->data[0].option.len = sizeof(CREDS_VALUE);
 	oa->data[0].value.data = (void *)creds;
 	oa->data[0].value.len = 0;

 	for (i = 0; i < count; i++) {
 		gssx_buffer dummy = { 0, NULL };
 		u32 length;

 		/* option buffer */
 		p = xdr_inline_decode(xdr, 4);
 		if (unlikely(p == NULL))
 			return -ENOSPC;

 		length = be32_to_cpup(p);
 		p = xdr_inline_decode(xdr, length);
 		if (unlikely(p == NULL))
 			return -ENOSPC;

 		if (length == sizeof(CREDS_VALUE) &&
 		    memcmp(p, CREDS_VALUE, sizeof(CREDS_VALUE)) == 0) {
 			/* We have creds here. parse them */
 			err = gssx_dec_linux_creds(xdr, creds);
 			if (err)
 				return err;
 			oa->data[0].value.len = 1; /* presence */
 		} else {
 			/* consume uninteresting buffer */
 			err = gssx_dec_buffer(xdr, &dummy);
 			if (err)
 				return err;
 		}
 	}
 	return 0;
 }



